33: _AppendPathList(
34:     std::vector<std::string>* result, 
35:     const std::string& paths, const std::string& sharedLibPath)
36: {
37:     for (const auto& path: TfStringSplit(paths, ARCH_PATH_LIST_SEP)) {
38:         if (path.empty()) {
39:             continue;
40:         }
41: 
42:         // Anchor all relative paths to the shared library path.
43:         const bool isLibraryRelativePath = TfIsRelativePath(path);
44:         if (isLibraryRelativePath) {
45:             std::string libraryRelativePath = 
46:                 TfStringCatPaths(sharedLibPath, path);
47:             // TfStringCatPaths will strip a trailing '/' character in path 
48:             // via ArchNormPath. This can cause the library relative path
49:             // to be treated as a file path downstream. Here we detect that case
50:             // and add the trailing '/' back if necessary. Note: trailing '\' is
51:             // converted to '/' on Windows.
52:             if (path.back() == '/') {
53:                 libraryRelativePath += path.back();
54:             }
55:             
56:             result->push_back(libraryRelativePath);
57:         }
58:         else {
59:             result->push_back(path);
60:         }
61:     }
62: }
