64: ARCH_CONSTRUCTOR(Plug_InitConfig, 2)
65: {
66:     std::vector<std::string> result;
67: 
68:     std::vector<std::string> debugMessages;
69: 
70:     // Determine the absolute path to the Plug shared library.  Any relative
71:     // paths specified in the plugin search path will be anchored to this
72:     // directory, to allow for relocatability.  Note that this can fail when pxr
73:     // is built as a static library.  In that case, fall back to using
74:     // ArchGetExecutablePath().  Also provide some diagnostic output if the
75:     // PLUG_INFO_SEARCH debug flag is enabled.
76:     std::string binaryPath;
77:     if (!ArchGetAddressInfo(
78:         reinterpret_cast<void*>(&Plug_InitConfig), &binaryPath,
79:             nullptr, nullptr, nullptr)) {
80:         debugMessages.emplace_back(
81:             "Failed to determine absolute path for Plug search "
82:             "using using ArchGetAddressInfo().  This is expected "
83:             "if pxr is linked as a static library.\n");
84:     }
85: 
86:     if (binaryPath.empty()) {
87:         debugMessages.emplace_back(
88:             "Using ArchGetExecutablePath() to determine absolute "
89:             "path for Plug search location.\n");
90:         binaryPath = ArchGetExecutablePath();
91:     }
92: 
93:     binaryPath = TfGetPathName(binaryPath);
94: 
95:     debugMessages.emplace_back(
96:         TfStringPrintf(
97:             "Plug will search for plug infos under '%s'\n",
98:             binaryPath.c_str()));
